script:
frappe.ui.form.on('Field Operation Log', {
	field: function(frm) {
		// Auto-populate farm from field
		if (frm.doc.field && !frm.doc.farm) {
			frappe.db.get_value('Field', frm.doc.field, 'farm', (r) => {
				if (r && r.farm) {
					frm.set_value('farm', r.farm);
				}
			});
		}

		// Get current crop project from field
		if (frm.doc.field && !frm.doc.crop_project) {
			frappe.db.get_value('Field', frm.doc.field, 'current_crop_project', (r) => {
				if (r && r.current_crop_project) {
					frm.set_value('crop_project', r.current_crop_project);
				}
			});
		}
	},

	operation_type: function(frm) {
		// Show PHI field only for Spraying
		if (frm.doc.operation_type === 'Spraying') {
			frm.set_df_property('pre_harvest_interval_days', 'hidden', 0);
			frm.set_df_property('pre_harvest_interval_days', 'reqd', 1);
		} else {
			frm.set_df_property('pre_harvest_interval_days', 'hidden', 1);
			frm.set_df_property('pre_harvest_interval_days', 'reqd', 0);
		}
	}
});
